typedef enum hwloc_obj_cache_type_e {
  HWLOC_OBJ_CACHE_UNIFIED,
  HWLOC_OBJ_CACHE_DATA,
  HWLOC_OBJ_CACHE_INSTRUCTION
} hwloc_obj_cache_type_t;

typedef enum hwloc_obj_bridge_type_e {
  HWLOC_OBJ_BRIDGE_HOST,
  HWLOC_OBJ_BRIDGE_PCI
} hwloc_obj_bridge_type_t;

enum hwloc_obj_osdev_type_e {
  HWLOC_OBJ_OSDEV_STORAGE = (1ULL<<0),
  HWLOC_OBJ_OSDEV_MEMORY = (1ULL<<1),
  HWLOC_OBJ_OSDEV_GPU = (1ULL<<2),
  HWLOC_OBJ_OSDEV_COPROC = (1ULL<<3),
  HWLOC_OBJ_OSDEV_NETWORK = (1ULL<<4),
  HWLOC_OBJ_OSDEV_OPENFABRICS = (1ULL<<5),
  HWLOC_OBJ_OSDEV_DMA = (1ULL<<6)
};

typedef unsigned long hwloc_obj_osdev_types_t;

struct hwloc_info_s {
  char *name;
  char *value;
};

struct hwloc_infos_s {
  struct hwloc_info_s *array;
  unsigned count;
  unsigned allocated;
};

struct hwloc_obj {
  hwloc_obj_type_t type;
  char *subtype;
  unsigned os_index;
#define HWLOC_UNKNOWN_INDEX (unsigned)-1
  char *name;
  hwloc_uint64_t total_memory;
  union hwloc_obj_attr_u *attr;
  int depth;
  unsigned logical_index;
  struct hwloc_obj *next_cousin;
  struct hwloc_obj *prev_cousin;
  struct hwloc_obj *parent;
  unsigned sibling_rank;
  struct hwloc_obj *next_sibling;
  struct hwloc_obj *prev_sibling;
  unsigned arity;
  struct hwloc_obj **children;
  struct hwloc_obj *first_child;
  struct hwloc_obj *last_child;
  int symmetric_subtree;
  unsigned memory_arity;
  struct hwloc_obj *memory_first_child;
  unsigned io_arity;
  struct hwloc_obj *io_first_child;
  unsigned misc_arity;
  struct hwloc_obj *misc_first_child;
  hwloc_cpuset_t cpuset;
  hwloc_cpuset_t complete_cpuset;
  hwloc_nodeset_t nodeset;
  hwloc_nodeset_t complete_nodeset;
  struct hwloc_infos_s infos;
  void *userdata;
  hwloc_uint64_t gp_index;
};
typedef struct hwloc_obj * hwloc_obj_t;

union hwloc_obj_attr_u {
  struct hwloc_numanode_attr_s { hwloc_uint64_t local_memory; } numanode;
  struct hwloc_cache_attr_s {
    hwloc_uint64_t size;
    unsigned depth;
    unsigned linesize;
    int associativity;
    hwloc_obj_cache_type_t type;
  } cache;
  struct hwloc_group_attr_s {
    unsigned depth;
    unsigned kind;
    unsigned subkind;
    unsigned char dont_merge;
  } group;
  struct hwloc_pcidev_attr_s {
    unsigned int domain;
    unsigned char bus;
    unsigned char dev;
    unsigned char func;
    unsigned char prog_if;
    unsigned short class_id;
    unsigned short vendor_id;
    unsigned short device_id;
    unsigned short subvendor_id;
    unsigned short subdevice_id;
    unsigned char revision;
    float linkspeed;
  } pcidev;
  struct hwloc_bridge_attr_s {
    union { struct hwloc_pcidev_attr_s pci; } upstream;
    hwloc_obj_bridge_type_t upstream_type;
    union { struct { unsigned int domain; unsigned char secondary_bus; unsigned char subordinate_bus; } pci; } downstream;
    hwloc_obj_bridge_type_t downstream_type;
    unsigned depth;
  } bridge;
  struct hwloc_osdev_attr_s { hwloc_obj_osdev_types_t types; } osdev;
};

