// No inputs required. Just call to exercise the return path.
unsigned v = hwloc_get_api_version();
// Basic property: version should be non-zero (header-defined versions are > 0)
FUZZ_ASSERT(v != 0, "hwloc_get_api_version returned 0");

// Generate two random types within the documented enum value range.
int tmin = (int)HWLOC_OBJ_TYPE_MIN;
int tmax = (int)HWLOC_OBJ_TYPE_MAX;
hwloc_obj_type_t type1 = (hwloc_obj_type_t)(tmin + (*FUZZ_PARAM(unsigned int) % (unsigned)(tmax - tmin + 1)));
hwloc_obj_type_t type2 = (hwloc_obj_type_t)(tmin + (*FUZZ_PARAM(unsigned int) % (unsigned)(tmax - tmin + 1)));
// Exercise comparison. No strict constraints on return value here.
(void)hwloc_compare_types(type1, type2);

int tmin = (int)HWLOC_OBJ_TYPE_MIN;
int tmax = (int)HWLOC_OBJ_TYPE_MAX;
hwloc_obj_type_t type = (hwloc_obj_type_t)(tmin + (*FUZZ_PARAM(unsigned int) % (unsigned)(tmax - tmin + 1)));
const char *s = hwloc_obj_type_string(type);
FUZZ_ASSERT(s != nullptr, "obj_type_string returned NULL");

// Prepare an input string and outputs per API requirements.
std::string in = FUZZ_PARAM_STR();
if (in.empty()) { in = "Machine"; }
hwloc_obj_type_t out_type;
// Randomly decide to provide attrp or not.
bool with_attr = (*FUZZ_PARAM(unsigned int) & 1u) != 0;
if (with_attr) {
  union hwloc_obj_attr_u attr;
  (void)hwloc_type_sscanf(in.c_str(), &out_type, &attr, sizeof(attr));
} else {
  (void)hwloc_type_sscanf(in.c_str(), &out_type, nullptr, 0);
}

// We expect infos to be a valid container (e.g., retrieved from a topology/object).
if (!infos) { FUZZ_BAIL(); }
// Choose an operation and satisfy its argument requirements.
unsigned long ops[] = { HWLOC_MODIFY_INFOS_OP_ADD, HWLOC_MODIFY_INFOS_OP_ADD_UNIQUE, HWLOC_MODIFY_INFOS_OP_REPLACE, HWLOC_MODIFY_INFOS_OP_REMOVE };
unsigned long op = ops[*FUZZ_PARAM(unsigned int) % (sizeof(ops)/sizeof(ops[0]))];
const char *name = nullptr;
const char *value = nullptr;
if (op == HWLOC_MODIFY_INFOS_OP_REMOVE) {
  // Either or both may be NULL. Randomize.
  if ((*FUZZ_PARAM(unsigned int) & 1u) != 0) { name = FUZZ_PARAM_STR().c_str(); }
  if ((*FUZZ_PARAM(unsigned int) & 2u) != 0) { value = FUZZ_PARAM_STR().c_str(); }
} else {
  // Required non-NULL name/value
  std::string n = FUZZ_PARAM_STR();
  std::string v = FUZZ_PARAM_STR();
  // Keep storage alive across the call
  name = n.c_str();
  value = v.c_str();
  (void)name; (void)value; // silence unused warnings for compilers without escape analysis
}
(void)hwloc_modify_infos(infos, op, name, value);

// Enforce: topology must have been successfully loaded.
if (!FUZZ_GET_ATTR_INT(topology, "loaded")) { FUZZ_BAIL(); }
// API expects hwloc_topology_t (handle), while the fuzzer provides hwloc_topology_t *; dereference it.
int d = hwloc_topology_get_depth(*topology);
FUZZ_ASSERT(d >= 0, "depth must be non-negative");

if (!FUZZ_GET_ATTR_INT(topology, "loaded")) { FUZZ_BAIL(); }
int tmin = (int)HWLOC_OBJ_TYPE_MIN;
int tmax = (int)HWLOC_OBJ_TYPE_MAX;
hwloc_obj_type_t type = (hwloc_obj_type_t)(tmin + (*FUZZ_PARAM(unsigned int) % (unsigned)(tmax - tmin + 1)));
(void)hwloc_get_type_depth(*topology, type);

if (!FUZZ_GET_ATTR_INT(topology, "loaded")) { FUZZ_BAIL(); }
bool pass_attr = (*FUZZ_PARAM(unsigned int) & 1u) != 0;
int tmin = (int)HWLOC_OBJ_TYPE_MIN;
int tmax = (int)HWLOC_OBJ_TYPE_MAX;
hwloc_obj_type_t type = (hwloc_obj_type_t)(tmin + (*FUZZ_PARAM(unsigned int) % (unsigned)(tmax - tmin + 1)));
if (pass_attr) {
  union hwloc_obj_attr_u attr; // stack buffer; library only reads
  size_t attrsize = sizeof(attr);
  (void)hwloc_get_type_depth_with_attr(*topology, type, &attr, attrsize);
} else {
  (void)hwloc_get_type_depth_with_attr(*topology, type, nullptr, 0);
}

if (!FUZZ_GET_ATTR_INT(topology, "loaded")) { FUZZ_BAIL(); }
int maxdepth = hwloc_topology_get_depth(*topology);
FUZZ_ASSERT(maxdepth >= 0, "invalid topology depth");
int depth;
if (maxdepth > 0 && ((*FUZZ_PARAM(unsigned int) & 1u) == 0)) {
  depth = (int)(*FUZZ_PARAM(unsigned int) % (unsigned)maxdepth);
} else {
  const int virtuals[] = {
    HWLOC_TYPE_DEPTH_NUMANODE,
    HWLOC_TYPE_DEPTH_BRIDGE,
    HWLOC_TYPE_DEPTH_PCI_DEVICE,
    HWLOC_TYPE_DEPTH_OS_DEVICE,
    HWLOC_TYPE_DEPTH_MISC,
    HWLOC_TYPE_DEPTH_MEMCACHE
  };
  depth = virtuals[*FUZZ_PARAM(unsigned int) % (sizeof(virtuals)/sizeof(virtuals[0]))];
}
(void)hwloc_get_depth_type(*topology, depth);

if (!FUZZ_GET_ATTR_INT(topology, "loaded")) { FUZZ_BAIL(); }
int maxdepth = hwloc_topology_get_depth(*topology);
FUZZ_ASSERT(maxdepth >= 0, "invalid topology depth");
int depth = (maxdepth > 0) ? (int)(*FUZZ_PARAM(unsigned int) % (unsigned)maxdepth)
                           : HWLOC_TYPE_DEPTH_NUMANODE;
(void)hwloc_get_nbobjs_by_depth(*topology, depth);

// Validate object belongs to a loaded topology.
void *stored_topo_ptr = FUZZ_GET_ATTR_PTR(obj, "topology");
if (!stored_topo_ptr) { FUZZ_BAIL(); }
hwloc_topology_t *topology = (hwloc_topology_t *)stored_topo_ptr;
if (!FUZZ_GET_ATTR_INT(topology, "loaded")) { FUZZ_BAIL(); }
size_t bufsz = (size_t)(*FUZZ_PARAM(unsigned int) % 512u);
std::string backing; backing.resize(bufsz);
char *buf = bufsz ? &backing[0] : nullptr;
unsigned long all = (unsigned long)(HWLOC_OBJ_SNPRINTF_FLAG_LONG_NAMES | HWLOC_OBJ_SNPRINTF_FLAG_SHORT_NAMES | HWLOC_OBJ_SNPRINTF_FLAG_MORE_ATTRS | HWLOC_OBJ_SNPRINTF_FLAG_NO_UNITS | HWLOC_OBJ_SNPRINTF_FLAG_UNITS_1000 | HWLOC_OBJ_SNPRINTF_FLAG_OLD_VERBOSE);
unsigned long flags = ((unsigned long)*FUZZ_PARAM(unsigned int)) & all;
(void)hwloc_obj_type_snprintf(buf, bufsz, *obj, flags);

void *stored_topo_ptr = FUZZ_GET_ATTR_PTR(obj, "topology");
if (!stored_topo_ptr) { FUZZ_BAIL(); }
hwloc_topology_t *topology = (hwloc_topology_t *)stored_topo_ptr;
if (!FUZZ_GET_ATTR_INT(topology, "loaded")) { FUZZ_BAIL(); }
size_t bufsz = (size_t)(*FUZZ_PARAM(unsigned int) % 512u);
std::string backing; backing.resize(bufsz);
char *buf = bufsz ? &backing[0] : nullptr;
std::string sep = FUZZ_PARAM_STR();
if (sep.empty()) { sep = ","; }
unsigned long all = (unsigned long)(HWLOC_OBJ_SNPRINTF_FLAG_LONG_NAMES | HWLOC_OBJ_SNPRINTF_FLAG_SHORT_NAMES | HWLOC_OBJ_SNPRINTF_FLAG_MORE_ATTRS | HWLOC_OBJ_SNPRINTF_FLAG_NO_UNITS | HWLOC_OBJ_SNPRINTF_FLAG_UNITS_1000 | HWLOC_OBJ_SNPRINTF_FLAG_OLD_VERBOSE);
unsigned long flags = ((unsigned long)*FUZZ_PARAM(unsigned int)) & all;
(void)hwloc_obj_attr_snprintf(buf, bufsz, *obj, sep.c_str(), flags);

if (!FUZZ_GET_ATTR_INT(topology, "loaded")) { FUZZ_BAIL(); }
struct hwloc_infos_s *infos = hwloc_topology_get_infos(*topology);
FUZZ_ASSERT(infos != nullptr, "topology infos should not be NULL");
// Track association for safety.
FUZZ_SET_ATTR_PTR(infos, "topology", (void*)topology);

// Ensure topology is loaded and obj belongs to it.
if (!FUZZ_GET_ATTR_INT(topology, "loaded")) { FUZZ_BAIL(); }
void *stored = FUZZ_GET_ATTR_PTR(obj, "topology");
if (!stored || stored != (void*)topology) { FUZZ_BAIL(); }
// Randomly set a new subtype or clear it (NULL).
bool clear = (*FUZZ_PARAM(unsigned int) & 1u) != 0;
std::string sub_storage = clear ? std::string() : FUZZ_PARAM_STR();
const char *sub = clear ? nullptr : sub_storage.c_str();
(void)hwloc_obj_set_subtype(*topology, *obj, sub);
if (!clear && sub) { FUZZ_SET_ATTR_STR(obj, "last_subtype", sub); }

// set must be allocated by caller; assume the pool provided a valid bitmap handle.
if (!set) { FUZZ_BAIL(); }
int flags = 0;
if ((*FUZZ_PARAM(unsigned int) & 1u) != 0) flags |= HWLOC_CPUBIND_PROCESS; else flags |= HWLOC_CPUBIND_THREAD;
