import random
import string
from typing import List, Tuple

# Generator for hwloc type/attr strings suitable for hwloc_type_sscanf()
# We build a mixture of plain types and types with attributes, including caches,
# groups, OS/PCI devices, NUMA nodes, and bridges. Results are designed to be valid
# and exercise different parsing paths. Output is a bytes buffer (UTF-8).

BASIC_TYPES = [
    "Machine", "Package", "Die", "Core", "PU",
    "Group", "NUMANode", "MemCache", "Bridge",
    "PCIDevice", "OSDevice", "Misc"
]

CACHE_LEVELS = ["L1", "L2", "L3", "L4", "L5"]
CACHE_KINDS = ["Cache", "ICache", "DCache"]
CACHE_TYPES = ["Unified", "Data", "Instruction"]

OSDEV_SUBTYPES = [
    "Storage", "Memory", "GPU", "CoProc", "Network", "OpenFabrics", "DMA"
]

BRIDGE_SIDES = ["Host", "PCI"]

PCI_CLASSES = [
    0x0100,  # mass storage / scsi
    0x0200,  # network
    0x0300,  # display
    0x0400,  # multimedia
    0x0600,  # bridge
    0x0c03,  # USB
]

# Utility to format sizes like hwloc often prints/parses (bytes, KB, MB)
SIZE_UNITS = ["B", "KB", "MB", "GB"]

def _rand_bool(r: random.Random, p_true: float = 0.5) -> bool:
    return r.random() < p_true

def _rand_size_string(r: random.Random) -> str:
    # Choose a power-of-two-ish size, with unit
    base = 2 ** r.choice([10, 12, 15, 16, 17, 20])  # 1KB, 4KB, 32KB, 64KB, 128KB, 1MB
    mult = r.choice([1, 2, 3, 4, 6, 8, 12, 16, 24, 32])
    size = base * mult
    unit = r.choice(SIZE_UNITS)
    if unit == "B":
        return f"{size}B"
    elif unit == "KB":
        return f"{size//1024}KB" if size % 1024 == 0 else f"{size/1024:.0f}KB"
    elif unit == "MB":
        return f"{size//(1024*1024)}MB" if size % (1024*1024) == 0 else f"{size/(1024*1024):.0f}MB"
    else:
        # GB
        return f"{size//(1024*1024*1024)}GB"

def _rand_cache_string(r: random.Random) -> str:
    # Examples accepted by hwloc: "L2Cache", "L3ICache", optionally with attributes
    level = r.choice(CACHE_LEVELS)
    kind = r.choice(CACHE_KINDS)
    base = level + kind  # e.g., L2Cache, L1ICache, L3DCache
    # Optionally append attributes in parentheses, common keys: size,depth,linesize,type
    attrs = []
    if _rand_bool(r, 0.9):
        attrs.append(f"size={_rand_size_string(r)}")
    if _rand_bool(r, 0.5):
        attrs.append(f"depth={r.choice([1,2,3,4,5,6,7,8])}")
    if _rand_bool(r, 0.6):
        # cache line sizes: typical 64, 128
        attrs.append(f"linesize={r.choice([32, 64, 128])}")
    if _rand_bool(r, 0.5):
        attrs.append(f"type={r.choice(CACHE_TYPES)}")
    if attrs:
        base += "(" + ",".join(attrs) + ")"
    return base

def _rand_group_string(r: random.Random) -> str:
    # Group or GroupN
    if _rand_bool(r):
        return "Group"
    else:
        return f"Group{r.randint(1, 32)}"

def _rand_osdev_string(r: random.Random) -> str:
    # Syntax commonly parsed: "OSDev:GPU", "OSDev:Network"
    return f"OSDev:{r.choice(OSDEV_SUBTYPES)}"

def _rand_pci_string(r: random.Random) -> str:
    # "PCIDevice" optionally with vendor/device/class ids
    s = "PCIDevice"
    attrs = []
    if _rand_bool(r, 0.8):
        attrs.append(f"vendor={r.randint(0x1000, 0xFFFF):04x}")
    if _rand_bool(r, 0.8):
        attrs.append(f"device={r.randint(0x0001, 0xFFFF):04x}")
    if _rand_bool(r, 0.6):
        attrs.append(f"class={r.choice(PCI_CLASSES):04x}")
    if _rand_bool(r, 0.5):
        attrs.append(f"revision={r.randint(0,255)}")
    if attrs:
        s += "(" + ",".join(attrs) + ")"
    return s

def _rand_bridge_string(r: random.Random) -> str:
    # "Bridge" or detailed side types: "Bridge(Up=Host,Down=PCI)"
    if _rand_bool(r, 0.4):
        return "Bridge"
    up = r.choice(BRIDGE_SIDES)
    down = r.choice(BRIDGE_SIDES)
    return f"Bridge(Up={up},Down={down})"

def _rand_numa_string(r: random.Random) -> str:
    # "NUMANode" optionally with memory size
    s = "NUMANode"
    if _rand_bool(r, 0.8):
        s += f"(memory={_rand_size_string(r)})"
    return s

def _rand_basic_named(r: random.Random) -> str:
    return r.choice(BASIC_TYPES)

def _rand_misc_string(r: random.Random) -> str:
    # "Misc" optionally with a name value "name=foo"
    s = "Misc"
    if _rand_bool(r, 0.6):
        # simple alphanum name
        name = ''.join(r.choices(string.ascii_letters + string.digits + "_-", k=r.randint(3, 12)))
        s += f"(name={name})"
    return s

def _rand_memcache_string(r: random.Random) -> str:
    # MemCache with size and depth
    s = "MemCache"
    attrs = []
    if _rand_bool(r, 0.9):
        attrs.append(f"size={_rand_size_string(r)}")
    if _rand_bool(r, 0.7):
        attrs.append(f"depth={r.randint(1, 8)}")
    if attrs:
        s += "(" + ",".join(attrs) + ")"
    return s

VARIANTS = [
    _rand_basic_named,
    _rand_group_string,
    _rand_cache_string,
    _rand_osdev_string,
    _rand_pci_string,
    _rand_bridge_string,
    _rand_numa_string,
    _rand_misc_string,
    _rand_memcache_string,
]

PREFIXES = ["", "type=", "Type="]

def _with_prefix(r: random.Random, s: str) -> str:
    # Sometimes hwloc_type_sscanf accepts a leading "type="
    if _rand_bool(r, 0.25):
        return r.choice(PREFIXES) + s
    return s

def _maybe_case_mix(r: random.Random, s: str) -> str:
    # Case-insensitive parser: randomly change case to test paths
    if not _rand_bool(r, 0.3):
        return s
    out = []
    for ch in s:
        if ch.isalpha():
            out.append(ch.upper() if _rand_bool(r, 0.5) else ch.lower())
        else:
            out.append(ch)
    return ''.join(out)

def _build_single(r: random.Random) -> str:
    s = r.choice(VARIANTS)(r)
    s = _with_prefix(r, s)
    s = _maybe_case_mix(r, s)
    return s

def _maybe_append_attrs(r: random.Random, s: str) -> str:
    # Some types also accept trailing info-like key=val pairs separated by spaces
    if not _rand_bool(r, 0.2):
        return s
    extras = []
    if _rand_bool(r, 0.5):
        extras.append(f"os_index={r.randint(0, 4095)}")
    if _rand_bool(r, 0.5):
        extras.append(f"name={''.join(r.choices(string.ascii_letters, k=r.randint(3,10)))}")
    if extras:
        s = s + " " + " ".join(extras)
    return s

def _compose_sequence(r: random.Random) -> str:
    # Occasionally generate a comma-separated list of types; some parsers accept only single,
    # but comma separated might still parse first entry; include to vary inputs while keeping first valid.
    if not _rand_bool(r, 0.15):
        return _maybe_append_attrs(r, _build_single(r))
    parts = [_build_single(r) for _ in range(r.randint(2, 4))]
    s = ",".join(parts)
    return s

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Choose one of several generation modes
    mode = r.random()
    if mode < 0.25:
        s = _build_single(r)
    elif mode < 0.6:
        s = _maybe_append_attrs(r, _build_single(r))
    elif mode < 0.85:
        s = _compose_sequence(r)
    else:
        # Favor cache descriptions heavily (rich attributes)
        s = _rand_cache_string(r)
        s = _maybe_case_mix(r, s)
    # Ensure non-empty and within size limits
    s = s.strip()
    if not s:
        s = "Machine"
    b = s.encode('utf-8')
    return b[:4096]

import random
from typing import List, Tuple

# Generator for valid hwloc XML buffers suitable for:
# - hwloc_topology_set_xmlbuffer (expects NUL-terminated; fuzzer appends NUL itself)
# - hwloc_topology_diff_load_xmlbuffer (expects an XML diff document)
#
# Strategy:
# - Produce a variety of small but valid hwloc XML topology documents and
#   hwloc XML diff documents. All are well-formed and within 4096 bytes.
# - Randomly vary counts, attributes, and structures to exercise parsing paths
#   while keeping documents valid for hwloc's XML loader.
# - The returned bytes never include an explicit NUL terminator; the stub that
#   requires it pushes one itself.
#
# Notes on formats (kept simple and conservative):
# Topology XML root element is <topology>. Objects are represented by <object>
# with attributes such as type, depth, os_index, name, cpuset, nodeset. Children
# are nested inside <object>. This resembles hwloc v2+ XML export and is widely
# accepted by the loader.
# Diff XML root is <topology_diff>. It contains <too_complex> and/or <obj_attr>
# entries. We emit simple obj_attr variants for size, name, and info changes.

SAFE_TYPES = [
    "Machine", "Package", "Die", "Core", "PU",
    "L1Cache", "L2Cache", "L3Cache",
    "NUMANode", "Group", "Bridge", "PCIDevice", "OSDevice", "Misc"
]

# Minimal hexadecimal bitmap strings commonly accepted by hwloc for sets.
# Keep them simple and valid.
BITMAPS = [
    "0x0", "0x1", "0x3", "0xf", "0xff", "0xffff", "0x5555", "0xaaaa",
]

OSDEV_SUBTYPES = [
    "network", "storage", "gpu", "coproc", "dma", "openfabrics", "memory"
]

CACHE_ATTRS = [
    ("L1Cache", 1, 32768, 64, "Data"),
    ("L1Cache", 1, 32768, 64, "Instruction"),
    ("L2Cache", 2, 262144, 64, "Unified"),
    ("L3Cache", 3, 8388608, 64, "Unified"),
]

# Helpers to build XML safely

def esc(s: str) -> str:
    return (s.replace("&", "&amp;")
             .replace("<", "&lt;")
             .replace(">", "&gt;")
             .replace('"', "&quot;")
             .replace("'", "&apos;"))


def attr(name: str, value: str) -> str:
    return f" {name}=\"{esc(value)}\""


def open_tag(name: str, attrs: List[Tuple[str, str]] = None) -> str:
    if not attrs:
        return f"<{name}>"
    parts = "".join(attr(k, v) for k, v in attrs)
    return f"<{name}{parts}>"


def empty_tag(name: str, attrs: List[Tuple[str, str]] = None) -> str:
    if not attrs:
        return f"<{name}/>"
    parts = "".join(attr(k, v) for k, v in attrs)
    return f"<{name}{parts}/>"


def close_tag(name: str) -> str:
    return f"</{name}>"


def rand_cpuset(rng: random.Random, max_bits: int) -> str:
    # Produce a contiguous mask like 0x0, 0x3, 0xf, etc., or pick from table.
    if rng.random() < 0.5:
        return rng.choice(BITMAPS)
    bits = rng.randint(0, max_bits)
    mask = (1 << bits) - 1 if bits > 0 else 0
    return f"0x{mask:x}"


def rand_nodeset(rng: random.Random, max_nodes: int) -> str:
    # Use the same hex mask style for nodeset
    if rng.random() < 0.5:
        return rng.choice(BITMAPS)
    bits = rng.randint(0, max_nodes)
    mask = (1 << bits) - 1 if bits > 0 else 0
    return f"0x{mask:x}"


def make_info_tags(rng: random.Random, count: int) -> str:
    out = []
    for i in range(count):
        name = f"key{i}"
        value = f"val{i}_{rng.randint(0, 1000)}"
        out.append(empty_tag("info", [("name", name), ("value", value)]))
    return "".join(out)


def make_cache_attrs_xml(cache_type: str, depth: int, size: int, linesize: int, kind: str) -> str:
    # Provide cache attributes as a child tag for clarity.
    return open_tag("cache", [("size", str(size)), ("depth", str(depth)), ("linesize", str(linesize)), ("type", kind)]) + close_tag("cache")


def make_object_xml(rng: random.Random, typ: str, depth: int, index: int, pu_span: int, numa_span: int, with_children: bool) -> str:
    attrs = [("type", typ), ("depth", str(depth)), ("os_index", str(index))]
    if rng.random() < 0.6:
        attrs.append(("name", f"{typ}{index}"))
    if typ in ("Core", "PU", "Machine", "Package", "Die", "Group"):
        attrs.append(("cpuset", rand_cpuset(rng, pu_span)))
    if typ in ("Machine", "NUMANode", "Package", "Group", "Die"):
        attrs.append(("nodeset", rand_nodeset(rng, numa_span)))

    pieces = [open_tag("object", attrs)]

    # Attach type-specific attributes
    if typ.endswith("Cache"):
        # Pick coherent attributes for cache
        ctyp, cdepth, csize, lsize, ckind = rng.choice(CACHE_ATTRS)
        # Ensure tag type is consistent with object type depth naming
        if not typ.startswith("L"):
            ctyp = typ
        pieces.append(make_cache_attrs_xml(ctyp, cdepth, csize, lsize, ckind))

    if typ == "OSDevice":
        pieces.append(empty_tag("osdev", [("class", rng.choice(OSDEV_SUBTYPES))]))

    # Optional infos
    if rng.random() < 0.7:
        pieces.append(make_info_tags(rng, rng.randint(0, 3)))

    # Children
    if with_children:
        child_count = rng.randint(0, 3)
        next_depth = depth + 1
        for i in range(child_count):
            ctype = rng.choice(["Core", "PU", "L1Cache", "L2Cache", "L3Cache", "NUMANode", "Group", "Misc"]) if typ not in ("PU", "NUMANode") else "PU"
            # Avoid infinite nesting for PUs and NUMANodes
            c_with_children = (ctype not in ("PU", "NUMANode") and next_depth < 6 and rng.random() < 0.6)
            pieces.append(make_object_xml(rng, ctype, next_depth, i, pu_span, numa_span, c_with_children))

    pieces.append(close_tag("object"))
    return "".join(pieces)


def build_topology_xml(rng: random.Random) -> str:
    # Build a compact but valid topology tree.
    pu_span = rng.randint(1, 64)  # up to 64 logical CPUs
    numa_span = rng.randint(1, 16)  # up to 16 NUMA nodes

    attrs = [("version", "2.0")]
    doc = ["<?xml version=\"1.0\" encoding=\"UTF-8\"?>", open_tag("topology", attrs)]

    # Machine root
    doc.append(make_object_xml(rng, "Machine", 0, 0, pu_span, numa_span, True))

    # Optionally add a second root child like a Misc info or Group
    if rng.random() < 0.5:
        doc.append(make_object_xml(rng, rng.choice(["Group", "Misc"]), 0, 1, pu_span, numa_span, rng.random() < 0.5))

    doc.append(close_tag("topology"))
    return "".join(doc)


def build_diff_obj_attr_size(rng: random.Random) -> str:
    # Change memory size on object at depth/index
    attrs = [
        ("obj_depth", str(rng.randint(0, 6))),
        ("obj_index", str(rng.randint(0, 32))),
        ("attr", "size"),
        ("index", str(rng.randint(0, 1))),
        ("oldvalue", str(rng.choice([0, 1048576, 2097152]))),
        ("newvalue", str(rng.choice([1048576, 2097152, 4194304])))
    ]
    return empty_tag("obj_attr", attrs)


def build_diff_obj_attr_name(rng: random.Random) -> str:
    attrs = [
        ("obj_depth", str(rng.randint(0, 6))),
        ("obj_index", str(rng.randint(0, 32))),
        ("attr", "name"),
        ("oldvalue", f"old{rng.randint(0,9)}"),
        ("newvalue", f"new{rng.randint(0,9)}"),
    ]
    return empty_tag("obj_attr", attrs)


def build_diff_obj_attr_info(rng: random.Random) -> str:
    attrs = [
        ("obj_depth", str(rng.randint(0, 6))),
        ("obj_index", str(rng.randint(0, 32))),
        ("attr", "info"),
        ("name", f"k{rng.randint(0,3)}"),
        ("oldvalue", f"v{rng.randint(0,3)}"),
        ("newvalue", f"v{rng.randint(4,7)}"),
    ]
    return empty_tag("obj_attr", attrs)


def build_diff_too_complex(rng: random.Random) -> str:
    attrs = [
        ("obj_depth", str(rng.randint(0, 6))),
        ("obj_index", str(rng.randint(0, 32))),
    ]
    return empty_tag("too_complex", attrs)


def build_diff_xml(rng: random.Random) -> str:
    # Build a small valid diff list
    parts = ["<?xml version=\"1.0\" encoding=\"UTF-8\"?>", open_tag("topology_diff")]
    count = rng.randint(1, 5)
    for _ in range(count):
        choice = rng.random()
        if choice < 0.4:
            parts.append(build_diff_obj_attr_size(rng))
        elif choice < 0.8:
            # mix name/info variants
            parts.append(build_diff_obj_attr_name(rng) if rng.random() < 0.5 else build_diff_obj_attr_info(rng))
        else:
            parts.append(build_diff_too_complex(rng))
    parts.append(close_tag("topology_diff"))
    return "".join(parts)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose between a topology XML and a diff XML to exercise both stubs
    if rng.random() < 0.6:
        xml = build_topology_xml(rng)
    else:
        xml = build_diff_xml(rng)

    data = xml.encode("utf-8")
    # Ensure we respect size constraints
    if len(data) > 4096:
        # If too large (unlikely), truncate safely at last closing tag boundary
        cut = data.rfind(b">", 0, 4096)
        if cut == -1:
            data = data[:4096]
        else:
            data = data[:cut+1]
    return data
